//! Unique original raw-derived generator fold. Owned identifier summaries only.
use crate::{reactive_original_source::ReadSource,reactive_reads_native::Failure,reactive_reaction_policy::{self as reaction,Procedure,ProcedureKey,Membership},reactive_reaction_native::{self as raw,ProcedureSelector},derived_reads_collect_policy as policy,key_policy_control::{self as kc,Control},derived_reads_policy::{OwnerSlots,ReactionSlots},pat};
use std::{collections::{BTreeMap,BTreeSet,HashSet},io};
struct Work<'a,'s>{source:&'a ReadSource<'s>}
impl Control for Work<'_,'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{self.source.checkpoint()?;if self.source.budget().denied(){return Err(Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"derived read admission refused")))}self.source.require()?;Ok(())}fn reserve(&mut self,n:usize)->Result<(),Failure>{self.source.budget().charge(n).map_err(|actual|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,actual)))}fn overflow(&mut self)->Failure{self.source.budget().deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"derived read capacity overflow"))}fn allocation_failed(&mut self)->Failure{self.overflow()}}
struct EveryName;impl Membership for EveryName{type Error=Failure;fn contains(&self,_:&str)->Result<bool,Failure>{Ok(true)}}
#[derive(Clone,PartialEq,Eq,Hash)]struct Key{relative:String,header:usize}
struct Summary{owner:String,name:String,key:Key,reads:Vec<(String,usize)>,calls:Vec<String>}
fn eligible(proc:&Procedure<'_>)->bool{proc.owner!="/"&&!reaction::GENERATED_SKIP_DIRS.iter().any(|prefix|proc.relative.starts_with(prefix))&&proc.relative!=reaction::GENERATED_REL&&!proc.owner.starts_with("/datum/capability")}
fn summary(proc:Procedure<'_>,key:ProcedureKey<'_>,include_reads:bool,include_calls:bool,work:&mut Work<'_,'_>)->Result<Summary,Failure>{work.checkpoint()?;let ProcedureKey::Raw{relative,header}=key else{return Err("native derived procedure lacks original raw coordinates".into())};let owner=kc::own(work,proc.owner)?;let name=kc::own(work,proc.name)?;let key=Key{relative:kc::own(work,relative)?,header};let reads=if include_reads{reaction::body_reads(&proc,&EveryName,work)?}else{Vec::new()};let calls=if include_calls{policy::called_names(proc.lines.iter(),work)?}else{Vec::new()};Ok(Summary{owner,name,key,reads,calls})}
fn append(source:&ReadSource<'_>,slots:&mut OwnerSlots,holder:&str,kind:&str,value:&str,reads:Vec<(String,usize)>,work:&mut Work<'_,'_>)->Result<(),Failure>{
 // SAME empty slot creation as old generated_text, even if no known reads.
 kc::reserve(work,||holder.len().checked_add(kind.len())?.checked_add(value.len())?.checked_mul(4)?.checked_add(2048))?;let owner=kc::own(work,holder)?;let kind=kc::own(work,kind)?;let value=kc::own(work,value)?;let slot=slots.entry(owner).or_default().entry((kind,value)).or_default();for(name,_)in reads{work.checkpoint()?;if raw::raw_has_variable(source,holder,&name)?&&!slot.contains(&name){crate::reactive_dependency_fold::row(work,slot)?;slot.push(name);}}Ok(())}
fn root_slots(source:&ReadSource<'_>,work:&mut Work<'_,'_>)->Result<OwnerSlots,Failure>{let mut pending=Vec::new();let mut visit=|key:ProcedureKey<'_>,proc:Procedure<'_>|{work.checkpoint()?;if !eligible(&proc)||(proc.name=="ui_data"&&proc.owner.starts_with("/datum/system")){return Ok(true)}if policy::proc_kind(proc.name).is_none()&&policy::derive_value(proc.name).is_none(){return Ok(true)}crate::reactive_dependency_fold::row(work,&mut pending)?;pending.push(summary(proc,key,true,false,work)?);Ok(true)};source.with_raw_procedures(ProcedureSelector::Names(&["should_run","draw","hidden_verbs","tgui_data","ui_data","push_to_rust"]),&mut visit)?;source.with_raw_procedures(ProcedureSelector::Prefix("derive_"),&mut visit)?;pending.sort_by(|a,b|(&a.owner,&a.key.relative,a.key.header).cmp(&(&b.owner,&b.key.relative,b.key.header)));let mut slots=OwnerSlots::new();for row in pending{work.checkpoint()?;let value=policy::derive_value(&row.name);if let Some(value)=value{if !raw::raw_has_variable(source,&row.owner,value)?{continue}}let kind=if value.is_some(){"derive"}else{policy::proc_kind(&row.name).ok_or("derived generator kind absent")?};append(source,&mut slots,&row.owner,kind,value.unwrap_or(""),row.reads,work)?;}Ok(slots)}
fn drawn_helpers(source:&ReadSource<'_>,slots:&mut OwnerSlots,work:&mut Work<'_,'_>)->Result<(),Failure>{let mut roots=Vec::new();source.with_raw_procedures(ProcedureSelector::Names(&["draw","hidden_verbs"]),&mut|key,proc|{work.checkpoint()?;if eligible(&proc){crate::reactive_dependency_fold::row(work,&mut roots)?;roots.push(summary(proc,key,false,true,work)?);}Ok(true)})?;
 for root in roots{work.checkpoint()?;kc::reserve(work,||root.owner.len().checked_add(1)?.checked_pow(2)?.checked_mul(16)?.checked_add(2048))?;let chain=policy::chain(&root.owner);let holder=kc::own(work,&root.owner)?;let mut seen=HashSet::new();kc::reserve(work,||root.key.relative.len().checked_mul(4)?.checked_add(1024))?;seen.insert(root.key.clone());let mut queue=Vec::new();crate::reactive_dependency_fold::row(work,&mut queue)?;queue.push(root);
 while let Some(parent)=queue.pop(){work.checkpoint()?;for name in parent.calls{let mut next=Vec::new();source.with_raw_procedures(ProcedureSelector::Names(&[&name]),&mut|key,proc|{work.checkpoint()?;if !eligible(&proc){return Ok(true)}kc::reserve(work,||proc.owner.len().checked_add(1)?.checked_pow(2)?.checked_mul(16)?.checked_add(2048))?;let above=chain.iter().any(|owner|owner==proc.owner);if !above&&!policy::chain(proc.owner).contains(&holder){return Ok(true)}let ProcedureKey::Raw{relative,header}=key else{return Err("draw helper lacks original raw coordinates".into())};if seen.iter().any(|key:&Key|key.relative==relative&&key.header==header){return Ok(true)}let child=summary(proc,key,true,true,work)?;kc::reserve(work,||child.key.relative.len().checked_mul(4)?.checked_add(1024))?;seen.insert(child.key.clone());crate::reactive_dependency_fold::row(work,&mut next)?;next.push(child);Ok(true)})?;
 for mut child in next{let target=if chain.contains(&child.owner){holder.as_str()}else{child.owner.as_str()};append(source,slots,target,"drawn","",std::mem::take(&mut child.reads),work)?;crate::reactive_dependency_fold::row(work,&mut queue)?;queue.push(child);}
 }}}
 Ok(())}
fn published_key(source:&ReadSource<'_>,owner:&str,name:&str,work:&mut Work<'_,'_>)->Result<Option<String>,Failure>{kc::reserve(work,||owner.len().checked_add(1)?.checked_pow(2)?.checked_mul(16)?.checked_add(2048))?;for ancestor in policy::chain(owner).into_iter().rev(){let mut found=None;source.with_reaction_code("PUBLISHED_BY",|relative,view|{work.checkpoint()?;if relative==reaction::GENERATED_REL{return Ok(true)}for(number,line)in view.numbered(){work.checkpoint()?;if line.starts_with('#'){continue}let pattern=pat!(r"PUBLISHED_BY\(\s*(/[\w/]+)\s*,\s*(\w+)\s*,\s*(\w+)\s*\)");kc::reserve(work,||pattern.capture_group_count().checked_mul(4)?.checked_mul(std::mem::size_of::<Option<(usize,usize)>>())?.checked_add(128))?;if let Some(matched)=pattern.captures(line){if matched.s(1)==ancestor&&matched.s(2)==name&&found.as_ref().is_none_or(|(file,at,_):&(String,usize,String)|(relative,number)>(file.as_str(),*at)){found=Some((kc::own(work,relative)?,number,kc::own(work,matched.s(3))?));}}}Ok(true)})?;if let Some((_,_,key))=found{return Ok(Some(key))}}Ok(None)}
pub(crate) fn generate(source:&ReadSource<'_>,test_types:&BTreeSet<String>)->Result<String,Failure>{let mut work=Work{source};work.checkpoint()?;let mut slots=root_slots(source,&mut work)?;drawn_helpers(source,&mut slots,&mut work)?;let mut reactions=ReactionSlots::new();for row in raw::reaction_reads(source)?{work.checkpoint()?;kc::reserve(&mut work,||row.owner.len().checked_mul(4)?.checked_add(2048))?;let slot=reactions.entry(kc::own(&mut work,&row.owner)?).or_default().entry(row.handler).or_default();for(name,_)in row.reads{let read=match published_key(source,&row.owner,&name,&mut work)?{Some(key)=>key,None=>kc::format(&mut work,format_args!("nameof({name})"))?};if !slot.contains(&read){crate::reactive_dependency_fold::row(&mut work,slot)?;slot.push(read);}}}
 let mut flags=BTreeMap::new();let mut members=BTreeSet::new();source.with_raw_procedures(ProcedureSelector::Names(&["reactions"]),&mut|_,proc|{work.checkpoint()?;if proc.owner!="/"&&!reaction::GENERATED_SKIP_DIRS.iter().any(|prefix|proc.relative.starts_with(prefix))&&proc.relative!=reaction::GENERATED_REL{policy::boot_declarations(proc.owner,proc.lines.iter(),&mut flags,&mut members,&mut work)?;}Ok(true)})?;kc::reserve(&mut work,||members.len().checked_mul(std::mem::size_of::<String>())?.checked_mul(4)?.checked_add(64))?;let members:Vec<_>=members.into_iter().collect();let text=crate::derived_reads_policy::generate_admitted(&slots,&reactions,&flags,&members,test_types,source.budget(),&||source.checkpoint())?;work.checkpoint()?;Ok(text)}

